let tierLocked=C.createSave(now);tierLocked.base[0].lvl=6;tierLocked.gunboat.level=7;tierLocked.gunboat.weaponLevels.fire=5;tierLocked.resources.gold=99999;let tierAt=now+200000;assert.equal(C.weaponLevelCap(tierLocked),6,'HQ6 caps weapons at Lv.6 even when a legacy save owns a Lv.7 gunboat');assert.match(C.upgradeWeapon(tierLocked,'fire',tierAt),/训练升级中/,'HQ6 must allow its Lv.5 weapon to reach Lv.6');C.settle(tierLocked,tierAt+C.weaponUpgradeSeconds(5)*1000,false);assert.equal(tierLocked.gunboat.weaponLevels.fire,6);assert.match(C.upgradeWeapon(tierLocked,'fire',tierAt+C.weaponUpgradeSeconds(5)*1000+1),/先升级司令部/);assert.match(C.upgradeGunboat(tierLocked,tierAt),/已高于司令部/,'legacy over-level gunboat is preserved but cannot advance');let tierReload=C.loadSave({getItem:()=>JSON.stringify(tierLocked)},tierAt+C.weaponUpgradeSeconds(5)*1000+2);assert.equal(tierReload.gunboat.level,7,'existing paid over-level gunboat must not be downgraded');assert.equal(tierReload.gunboat.weaponLevels.fire,6,'loading a save must retain the legal HQ6 weapon level');let highWeaponBattle=new C.Battle([{id:1,type:'hq',x:0,z:0,lvl:7}],66,'attack',null,7,C.MAP.spawnZ,24,{fire:7,barrage:7,flare:7,medkit:7,shock:7});assert.equal(highWeaponBattle.weaponLevels.fire,7);highWeaponBattle.useSkill('fire',0,0);assert.equal(highWeaponBattle.gunboatShells[0].damage,213,'levels above five use diminishing weapon growth');assert.ok(C.weaponUpgradeCost('fire',6)[0]>C.weaponUpgradeCost('fire',5)[0]&&C.weaponUpgradeSeconds(6)>C.weaponUpgradeSeconds(5),'late weapon levels must get materially more expensive and slower');
let slots=C.createSave(now);slots.base[0].lvl=2;slots.base.push({id:2,type:'gold',x:-8,z:4,lvl:1,stored:0});assert.match(C.startUpgrade(slots,2,now),/升级中/);let peopleBefore=C.clone(slots.army);assert.match(C.upgradeUnit(slots,'rifle',now),/训练升级中/,'training and engineering slots run in parallel');assert.deepEqual(slots.army,peopleBefore,'training upgrades a type and never creates idle personnel');assert.equal(slots.training[0].unit,'rifle');let slotGold=slots.resources.gold;assert.match(C.upgradeUnit(slots,'heavy',now),/训练位忙碌/);assert.match(C.buildAt(slots,'wood',8,4,now),/当前升级完成/);assert.equal(slots.resources.gold,slotGold,'blocked second jobs spend nothing');let constructionSlot=C.createSave(now);constructionSlot.base[0].lvl=2;assert.match(C.buildAt(constructionSlot,'gold',-8,4,now),/开工/);assert.match(C.upgradeGunboat(constructionSlot,now),/建造\/升级位忙碌/);assert.match(C.upgradeUnit(constructionSlot,'rifle',now),/训练升级中/,'construction can run beside one training upgrade');
for(let level=1;level<=C.MAX_HQ_LEVEL;level++){let tier=C.HQ_TIERS[level],state=C.createSave(now);state.base[0].lvl=level;state.craft.levels.fill(level);assert.equal(C.maxBoats(state),tier.boats);assert.equal(C.boatCapacity(state,1),tier.boatCapacity);assert.deepEqual(C.HQ_BUILD_LIMITS[level],tier.build);assert.equal(tier.build.wood,1,'each HQ tier permits only one lumber mill');assert.equal(tier.build.steel,1,'each HQ tier permits only one steelworks');assert.equal(tier.build.vault,1,'every HQ tier permits exactly one vault');assert.equal(C.npcBuildCounts(level).vault,1,'NPCs use the same singleton vault quota');assert.ok(tier.npc[0]<=level&&tier.npc[1]>=level)}
