function progressionState(level,buildingLevel,trainingLevel=buildingLevel){let state=C.createSave(now);state.base[0].lvl=level;state.resources={gold:99999,wood:99999,steel:99999};let id=2;for(let [type,count] of Object.entries(C.HQ_BUILD_LIMITS[level]))if(type!=='store')for(let i=0;i<count;i++)state.base.push({id:id++,type,x:0,z:0,lvl:buildingLevel,...(C.RES.includes(type)?{stored:0}:{})});for(let type of Object.keys(C.UNIT))if(C.UNLOCK[type]<=level)state.unitLevels[type]=trainingLevel;state.gunboat.level=Math.max(state.gunboat.level,trainingLevel);for(let kind of Object.keys(C.SKILLS))state.gunboat.weaponLevels[kind]=trainingLevel;return state}
let sixReady=progressionState(6,4),sixStatus=C.hqUpgradeStatus(sixReady);assert.equal(sixStatus.minimumAverage,4,'HQ6 uses the rounded-up 60% threshold');assert.equal(sixStatus.average,4);assert.equal(sixStatus.ready,true);assert.match(C.startUpgrade(sixReady,1,now),/司令部升级中/,'a complete HQ6 base with 4.0 average may advance');
let sixLow=progressionState(6,3);assert.equal(C.hqUpgradeStatus(sixLow).ready,false);assert.match(C.startUpgrade(sixLow,1,now),/平均 3\.0 \/ 4\.0/,'HQ6 cannot advance below average level 4');
let sixMissing=progressionState(6,6,6);sixMissing.base.splice(sixMissing.base.findIndex(b=>b.type==='sniper'),1);assert.equal(C.hqUpgradeStatus(sixMissing).allBuilt,false);assert.match(C.startUpgrade(sixMissing,1,now),/先建完 狙击塔×1/,'high levels cannot compensate for a missing required building');
let compensated=progressionState(3,2);compensated.base.find(b=>b.type==='sniper').lvl=1;compensated.base.find(b=>b.type==='gold').lvl=3;let compensatedStatus=C.hqUpgradeStatus(compensated);assert.equal(compensatedStatus.minimumAverage,2);assert.equal(compensatedStatus.average,2);assert.equal(compensatedStatus.ready,true,'one low building may be balanced by another upgraded building');
let perBoat=C.createSave(now);perBoat.base[0].lvl=2;let craftPrice=C.craftUpgradeCost(perBoat,0),craftGold=perBoat.resources.gold;assert.match(C.upgradeCraft(perBoat,0,now),/1 号登陆艇升级中/);assert.deepEqual(perBoat.craft.levels,[1,1,1]);C.settle(perBoat,now+28000,false);assert.deepEqual(perBoat.craft.levels,[2,1,1]);assert.deepEqual([0,1,2].map(i=>C.boatCapacity(perBoat,i)),[10,8,8]);assert.equal(C.capacity(perBoat),26);assert.equal(perBoat.resources.gold,craftGold-craftPrice[0]);
