const primedDefense=(type,level,ruleset=26)=>{let fight=new C.Battle([{id:1,type:'hq',x:20,z:20,lvl:1},{id:2,type,x:0,z:0,lvl:level}],700+level,'defense',null,1,C.MAP.spawnZ,ruleset),target={id:1,type:'tank',x:6,z:0,level,hp:100000,maxHp:100000,cool:1e9,walk:0,runUntil:0},weapon=fight.base[1];fight.units.push(target);weapon.targetId=target.id;weapon.heading=Math.PI/2;weapon.turnVelocity=0;weapon.lockReady=true;weapon.lockStart=-100;weapon.cool=0;return {fight,target,weapon}};
for(let level of [1,2,4,7]){let {fight,weapon}=primedDefense('rocket',level);fight.step();let tubes=C.rocketTubeCount(level),volley=fight.projectiles.filter(p=>p.weapon==='rocket'),expected=C.BUILD.rocket.damage*(1+.12*(level-1))*4;assert.equal(volley.length,tubes,`rocket Lv.${level} must fire every loaded tube`);assert.ok(Math.abs(volley.reduce((sum,p)=>sum+p.damage,0)-expected)<1e-9,`rocket Lv.${level} must divide, not multiply, total volley damage`);assert.deepEqual(volley.map(p=>p.lane),Array.from({length:tubes},(_,i)=>i));assert.equal(weapon.cool,C.BUILD.rocket.period,'tube count must not change rocket reload time')}
{let {fight,target,weapon}=primedDefense('missile',7);fight.step();weapon.cool=0;fight.step();let shots=fight.projectiles.filter(p=>p.weapon==='missile');assert.equal(shots.length,2,'a four-tube missile rack still fires only one missile per attack');assert.deepEqual(shots.map(p=>p.lane),[0,1],'missiles must rotate through tube positions in order');assert.ok(shots.every(p=>p.tubeCount===4&&p.damage===C.missileDamage(7,target)),'missile damage must remain whole rather than being split by tube count')}
{let {fight,weapon}=primedDefense('cannon',7);fight.step();weapon.cool=0;fight.step();let shots=fight.projectiles.filter(p=>p.weapon==='cannon');assert.equal(shots.length,2,'a triple cannon still fires one shell per attack');assert.deepEqual(shots.map(p=>p.lane),[0,1],'cannon barrels must fire in sequence');assert.ok(shots.every(p=>p.tubeCount===3&&p.damage===C.BUILD.cannon.damage*(1+.12*6)),'cannon damage must not be multiplied or divided by barrel count');assert.equal(weapon.cool,C.BUILD.cannon.period,'cannon fire rate must not change with barrel count')}
{let {fight,weapon}=primedDefense('mg',7);fight.step();weapon.cool=0;fight.step();let shots=fight.events.filter(e=>e.kind==='hit'&&e.weapon==='mg');assert.deepEqual(shots.map(e=>e.lane),[0,1],'machine-gun barrels must fire in sequence');assert.ok(shots.every(e=>e.tubeCount===6),'late machine guns must expose all six visual barrels');assert.equal(weapon.cool,C.BUILD.mg.period,'machine-gun fire rate must stay unchanged')}
{let {fight}=primedDefense('missile',7,25);fight.step();assert.equal(fight.projectiles.filter(p=>p.weapon==='missile').length,1);assert.equal(fight.projectiles.find(p=>p.weapon==='missile').tubeCount,1,'v25 replay must retain its single missile muzzle');let snapshot=fight.snapshot();assert.equal(snapshot.version,25,'historical replay version must not be rewritten')}
{let cluster=[{id:1,type:'hq',x:10,z:10,lvl:1},{id:2,type:'gold',x:-.65,z:-.65,lvl:1},{id:3,type:'gold',x:.65,z:-.65,lvl:1},{id:4,type:'gold',x:-.65,z:.65,lvl:1},{id:5,type:'gold',x:.65,z:.65,lvl:1},{id:6,type:'gold',x:1.35,z:0,lvl:1}],artillery=new C.Battle(cluster,812);artillery.fire(0,0);for(let i=0;i<28;i++)artillery.step();assert.deepEqual(artillery.base.slice(1).map(b=>b.hp<b.maxHp),[true,true,true,true,false],'one gunboat shell must cover a tight 2×2 block but cap at four buildings');let barrage=new C.Battle(cluster,813);barrage.gunboatShells.push({x:0,z:0,kind:'barrage',radius:C.SKILLS.barrage.radius,damage:10,start:0,land:1,lane:0});barrage.step();assert.ok(barrage.base.slice(1).every(b=>b.hp<b.maxHp),'each individual barrage rocket must apply uncapped area damage')}
let missilePriority=new C.Battle([{id:1,type:'hq',x:12,z:-10,lvl:6},{id:2,type:'missile',x:0,z:0,lvl:6}],330,'defense'),nearInfantry=heldUnit(1,'rifle',5,0,6),farTank=heldUnit(2,'tank',6,0,6);missilePriority.units.push(nearInfantry,farTank);for(let i=0;i<300&&!missilePriority.projectiles.length;i++){missilePriority.step();nearInfantry.x=5;nearInfantry.z=0;farTank.x=6;farTank.z=0}assert.equal(missilePriority.base[1].targetId,nearInfantry.id,'anti-tank missile launcher must retain normal nearest-target priority');assert.equal(missilePriority.projectiles[0].targetId,nearInfantry.id);assert.equal(missilePriority.projectiles[0].weapon,'missile');
let trackingBattle=new C.Battle([{id:1,type:'hq',x:12,z:-10,lvl:1},{id:2,type:'cannon',x:0,z:0,lvl:1}],331,'defense'),trackingTarget=heldUnit(1,'tank',6,0);trackingBattle.units.push(trackingTarget);for(let i=0;i<250&&!trackingBattle.base[1].lockReady;i++){trackingBattle.step();trackingTarget.x=6;trackingTarget.z=0}let trackingGun=trackingBattle.base[1];assert.equal(trackingGun.lockReady,true,'first target must finish a real acquisition before firing');trackingGun.cool=0;trackingTarget.x=0;trackingTarget.z=6;let trackingShots=trackingBattle.projectiles.length,trackingHeading=trackingGun.heading;trackingBattle.step();assert.equal(trackingBattle.projectiles.length,trackingShots+1,'a completed lock must keep firing while the turret catches up to a moving target');assert.equal(trackingGun.lockReady,true,'tracking movement must not revoke a completed lock');assert.ok(trackingGun.heading<trackingHeading,'the barrel must visibly begin turning toward the moved target');
let handoffBattle=new C.Battle([{id:1,type:'hq',x:12,z:-10,lvl:1},{id:2,type:'cannon',x:0,z:0,lvl:1}],332,'defense'),firstTarget=heldUnit(1,'tank',6,0),closeTarget=heldUnit(2,'tank',12,0),farTarget=heldUnit(3,'tank',12,4);handoffBattle.units.push(firstTarget,closeTarget,farTarget);for(let i=0;i<250&&!handoffBattle.base[1].lockReady;i++){handoffBattle.step();firstTarget.x=6;firstTarget.z=0;closeTarget.x=12;closeTarget.z=0;farTarget.x=12;farTarget.z=4}let handoffGun=handoffBattle.base[1];firstTarget.hp=0;closeTarget.x=6;closeTarget.z=.2;handoffGun.cool=0;let closeShots=handoffBattle.projectiles.length;handoffBattle.step();assert.equal(handoffGun.targetId,closeTarget.id);assert.equal(handoffGun.lockReady,true,'tightly grouped targets must preserve completed lock');assert.equal(handoffBattle.projectiles.length,closeShots+1,'tightly grouped targets should hand off fire without a dead interval');closeTarget.hp=0;farTarget.x=0;farTarget.z=6;handoffGun.cool=0;let farShots=handoffBattle.projectiles.length;handoffBattle.step();assert.equal(handoffGun.targetId,farTarget.id);assert.equal(handoffGun.lockReady,false,'a large-angle target change must reacquire');assert.equal(handoffBattle.projectiles.length,farShots,'large-angle handoff must not fire instantly');
let reloadBattle=new C.Battle([{id:1,type:'hq',x:12,z:-10,lvl:1},{id:2,type:'cannon',x:0,z:0,lvl:1}],333,'defense'),reloadTarget=heldUnit(1,'tank',12,0);reloadBattle.units.push(reloadTarget);let reloadGun=reloadBattle.base[1];reloadGun.cool=10;for(let i=0;i<5;i++){reloadBattle.step();reloadTarget.x=12;reloadTarget.z=0}assert.equal(reloadGun.cool,5,'reload must continue while no target is in range');reloadTarget.x=6;reloadTarget.z=0;for(let i=0;i<3;i++){reloadBattle.step();reloadTarget.x=6;reloadTarget.z=0}assert.equal(reloadGun.cool,2,'reload must continue while traversing to the next target');assert.equal(reloadGun.lockReady,false,'turning time must not be skipped merely because reload is almost complete');
